@code {
    private static readonly IReadOnlyList<string> stepNames = new List<string>
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int currentStep;
    private HashSet<int> completedSteps = new();
    private string? errorMessage;
    private bool isValidating;
    private bool isSubmitting;
    private int? submittedId;

    // Step 1
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> references = new() { new(), new() };

    // Step 4
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        errorMessage = null;
        currentStep = step;
    }

    // Step 1 logic
    private async Task NextFromPersonalInfo()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email) ||
            string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            errorMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!emailValid)
            {
                errorMessage = "The email address is not valid. Please check and try again.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        completedSteps.Add(0);
        currentStep = 1;
    }

    // Step 2 logic
    private void UpdateWorkEntry(int index, WorkEntryModel entry)
    {
        workEntries[index] = entry;
    }

    private void AddWorkEntry()
    {
        workEntries.Add(new WorkEntryModel());
    }

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void NextFromWorkHistory()
    {
        errorMessage = null;

        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        completedSteps.Add(1);
        currentStep = 2;
    }

    // Step 3 logic
    private void UpdateReference(int index, ReferenceModel entry)
    {
        references[index] = entry;
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private void NextFromReferences()
    {
        errorMessage = null;

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Each reference requires a name, relationship, and email.";
                return;
            }
        }

        completedSteps.Add(2);
        currentStep = 3;
    }

    // Step 4 logic
    private void NextFromCoverLetter()
    {
        errorMessage = null;
        completedSteps.Add(3);
        currentStep = 4;
    }

    // Step 5 logic
    private async Task SubmitApplication()
    {
        errorMessage = null;
        isSubmitting = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

